namespace BatchRenameStudio.Core;

/// <summary>
/// Assembles a <see cref="RenamePlan"/> from a set of files and a
/// <see cref="RuleSet"/> (BUILD-SPEC C3-C14). <see cref="Build"/> is pure:
/// no filesystem access.
/// </summary>
public static class PlanBuilder
{
    /// <summary>Pure: no filesystem access. Applies C3-C14 to an already-scanned set.</summary>
    public static RenamePlan Build(IEnumerable<FileEntry> files, RuleSet rules)
    {
        var sorted = FileSorter.Sort(files, rules.Sort);

        var originals = new List<string>(sorted.Count);
        var proposedNames = new List<string>(sorted.Count);

        for (var i = 0; i < sorted.Count; i++)
        {
            var original = sorted[i].Name;
            originals.Add(original);

            string proposed;
            if (rules.ApplyTo == ApplyToMode.Name)
            {
                NameSplitter.Split(original, out var target, out var ext);
                foreach (var step in rules.Steps)
                {
                    var counter = CounterFor(step, i);
                    if (step.Op == StepOp.Extension)
                    {
                        ext = ApplyExtension(ext, step);
                    }
                    else
                    {
                        target = ApplyTextStep(target, step, counter);
                    }
                }

                proposed = NameSplitter.Join(target, ext);
            }
            else
            {
                var target = original;
                foreach (var step in rules.Steps)
                {
                    var counter = CounterFor(step, i);
                    if (step.Op == StepOp.Extension)
                    {
                        NameSplitter.Split(target, out var b, out var e);
                        target = NameSplitter.Join(b, ApplyExtension(e, step));
                    }
                    else
                    {
                        target = ApplyTextStep(target, step, counter);
                    }
                }

                proposed = target;
            }

            proposedNames.Add(proposed);
        }

        // originals: proposed name (case-insensitive) -> indices whose ORIGINAL name matches it.
        var originalsByName = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
        for (var i = 0; i < originals.Count; i++)
        {
            if (!originalsByName.TryGetValue(originals[i], out var list))
            {
                list = new List<int>();
                originalsByName[originals[i]] = list;
            }

            list.Add(i);
        }

        // proposedCnt: proposed name (case-insensitive) -> count across ALL items (F1).
        var proposedCnt = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var proposed in proposedNames)
        {
            proposedCnt[proposed] = proposedCnt.TryGetValue(proposed, out var c) ? c + 1 : 1;
        }

        var plan = new RenamePlan();
        var summary = new PlanSummary();

        for (var i = 0; i < sorted.Count; i++)
        {
            var original = originals[i];
            var proposed = proposedNames[i];

            PlanStatus status;
            string reason;

            if (NameValidator.IsInvalid(proposed, out var invalidReason))
            {
                status = PlanStatus.Invalid;
                reason = invalidReason;
            }
            else if (HasOtherOriginalMatch(originalsByName, proposed, i) || proposedCnt[proposed] > 1)
            {
                status = PlanStatus.Collision;
                reason = "name conflict";
            }
            else if (string.Equals(proposed, original, StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = "";
            }
            else
            {
                status = PlanStatus.Ok;
                reason = "";
            }

            plan.Items.Add(new PlanItem
            {
                Original = original,
                Proposed = proposed,
                Status = status,
                Reason = reason,
            });

            switch (status)
            {
                case PlanStatus.Ok: summary.Ok++; break;
                case PlanStatus.Collision: summary.Collision++; break;
                case PlanStatus.Unchanged: summary.Unchanged++; break;
                case PlanStatus.Invalid: summary.Invalid++; break;
            }
        }

        summary.Total = plan.Items.Count;
        plan.Summary = summary;
        return plan;
    }

    /// <summary>Convenience: Scan + Build.</summary>
    public static RenamePlan BuildForDirectory(string directory, RuleSet rules)
    {
        return Build(DirectoryScanner.Scan(directory), rules);
    }

    private static bool HasOtherOriginalMatch(Dictionary<string, List<int>> originalsByName, string proposed, int selfIndex)
    {
        if (!originalsByName.TryGetValue(proposed, out var indices))
        {
            return false;
        }

        foreach (var j in indices)
        {
            if (j != selfIndex)
            {
                return true;
            }
        }

        return false;
    }

    private static long CounterFor(RuleStep step, int index)
    {
        return step.Start + (long)index * step.Step; // F2
    }

    private static string ApplyTextStep(string input, RuleStep step, long counter)
    {
        switch (step.Op)
        {
            case StepOp.Replace:
                return TextOps.Replace(input, step);
            case StepOp.Insert:
                return TextOps.Insert(input, step);
            case StepOp.Remove:
                return TextOps.Remove(input, step);
            case StepOp.Case:
                return step.Case switch
                {
                    CaseMode.Upper => input.ToUpperInvariant(),
                    CaseMode.Lower => input.ToLowerInvariant(),
                    CaseMode.Title => TextOps.TitleCase(input),
                    _ => input,
                };
            case StepOp.Sequence:
            {
                var rendered = TextOps.RenderSequence(step.Pattern, counter);
                return step.SequenceAt == SequencePosition.Prefix ? rendered + input : input + rendered;
            }
            case StepOp.Extension:
            case StepOp.Unknown:
            default:
                return input;
        }
    }

    private static string ApplyExtension(string ext, RuleStep step)
    {
        return step.Extension switch
        {
            ExtensionMode.Lower => ext.ToLowerInvariant(),
            ExtensionMode.Upper => ext.ToUpperInvariant(),
            ExtensionMode.Set => step.Value,
            _ => ext,
        };
    }
}

