using System.Collections.Concurrent;
using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// Primitive text transforms used by <see cref="PlanBuilder"/> (BUILD-SPEC
/// C6-C10, F5-F10).
/// </summary>
public static class TextOps
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);

    private static readonly ConcurrentDictionary<(string Pattern, bool IgnoreCase), Regex?> RegexCache = new();

    private static readonly Regex SequenceTokenRegex = new(@"\{n:(0+)\}", RegexOptions.Compiled);

    public static string Replace(string input, RuleStep s)
    {
        if (!s.UseRegex)
        {
            if (s.Find.Length == 0)
            {
                return input; // F5
            }

            return input.Replace(
                s.Find,
                s.ReplaceWith,
                s.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
        }

        var regex = RegexCache.GetOrAdd((s.Find, s.IgnoreCase), key =>
        {
            var options = RegexOptions.None;
            if (key.IgnoreCase)
            {
                options |= RegexOptions.IgnoreCase | RegexOptions.CultureInvariant;
            }

            try
            {
                return new Regex(key.Pattern, options, RegexTimeout);
            }
            catch (ArgumentException)
            {
                return null; // invalid pattern -> cached no-op (F7)
            }
        });

        if (regex is null)
        {
            return input; // F7
        }

        try
        {
            return regex.Replace(input, s.ReplaceWith);
        }
        catch (RegexMatchTimeoutException)
        {
            return input; // F7
        }
    }

    public static string Insert(string input, RuleStep s)
    {
        return s.InsertAt switch
        {
            InsertPosition.Prefix => s.Text + input,
            InsertPosition.Suffix => input + s.Text,
            InsertPosition.Index => input.Insert(Math.Clamp(s.Index, 0, input.Length), s.Text),
            _ => input,
        };
    }

    public static string Remove(string input, RuleStep s)
    {
        var from = Math.Clamp(s.From, 0, input.Length);
        var count = Math.Clamp(s.Count, 0, input.Length - from);
        return input.Remove(from, count);
    }

    public static string TitleCase(string input)
    {
        var sb = new StringBuilder(input.Length);
        var atRunStart = true;
        foreach (var c in input)
        {
            if (char.IsLetter(c))
            {
                sb.Append(atRunStart ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c));
                atRunStart = false;
            }
            else
            {
                sb.Append(c);
                atRunStart = true;
            }
        }

        return sb.ToString();
    }

    public static string RenderSequence(string pattern, long counter)
    {
        var match = SequenceTokenRegex.Match(pattern);
        if (!match.Success)
        {
            return pattern; // F8
        }

        var width = match.Groups[1].Value.Length;
        var rendered = counter.ToString(new string('0', width), CultureInfo.InvariantCulture);
        return pattern[..match.Index] + rendered + pattern[(match.Index + match.Length)..]; // F9
    }
}
